// SAM | 2026-10-30 11:08 +08:00 | Shared by the standalone tools: the Luatools-derived files each tool bundles, their exact version, and a check against
// the Luatools installed on this PC, so that after a Luatools upgrade the operator is told which files no longer match.
// The data lives in luatools_deps.json next to the exe (generated by tools/toolkit/gen_deps.py from the bundled files; sha256 are of the real bytes).
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;

namespace YpDeps
{
    public static class Deps
    {
        public const string FileName = "luatools_deps.json";

        static string Sha(string path) { using (var s = SHA256.Create()) using (var f = File.OpenRead(path)) return BitConverter.ToString(s.ComputeHash(f)).Replace("-", "").ToLowerInvariant(); }
        static string S(object o) { return o == null ? "" : Convert.ToString(o); }
        static Dictionary<string, object> D(object o) { return o as Dictionary<string, object>; }

        public static Dictionary<string, object> Load(string dir)
        {
            string p = Path.Combine(dir, FileName);
            if (!File.Exists(p)) return null;
            try { return new JavaScriptSerializer().Deserialize<Dictionary<string, object>>(File.ReadAllText(p, Encoding.UTF8)); } catch { return null; }
        }

        public static string Banner(string dir)
        {
            var d = Load(dir);
            if (d == null) return "依赖版本信息缺失（找不到 " + FileName + "）";
            var l = D(d["luatools"]); var soc = D(d["soc"]);
            return "依赖：Luatools " + S(l["version"]) + "（构建 " + S(l["build"]) + "）｜脚本资源 " + S(l["resource_version"]) + "｜底包 " + S(soc["name"]).Replace("LuatOS-SoC_", "").Replace(".soc", "");
        }

        // The Luatools version is only printed in its logs ("LuaTools version:  v3.4.14 ...").
        public static string InstalledVersion(string luatools)
        {
            string logs = Path.Combine(luatools, "log");
            if (!Directory.Exists(logs)) return null;
            foreach (string f in Directory.GetFiles(logs, "*.txt").OrderByDescending(x => new FileInfo(x).LastWriteTimeUtc).Take(12))
                try
                {
                    string t = File.ReadAllText(f, Encoding.Default);
                    var m = Regex.Matches(t, @"LuaTools version:\s+(v[0-9.]+)");
                    if (m.Count > 0) return m[m.Count - 1].Groups[1].Value;
                }
                catch { }
            return null;
        }

        // Prints what the tool depends on; with an installed Luatools folder also compares it. Returns the number of items that need attention.
        public static int Report(string dir, string tool, string luatools, Action<string> log, Action<string, string> logc = null)
        {
            // SAM | 2026-10-30 11:58 +08:00 | Green = no impact, nothing to do; red = must be handled. Only a broken bundle is red: Luatools changes on this PC never touch the pinned bundled files.
            Action<string, string> say = (c, t) => { if (logc != null) logc(c, t); else log(t); };
            var d = Load(dir);
            if (d == null) { say("red", "  ERROR 找不到 " + FileName + "，工具包不完整，必须重新拿一份完整的工具包"); return 1; }
            var l = D(d["luatools"]); var soc = D(d["soc"]);
            int attention = 0, notices = 0;
            log("[依赖版本] 工具包依赖表：" + S(d["toolkit_version"]) + "（生成 " + S(d["generated"]) + "）");
            log("  Luatools      " + S(l["version"]) + "（构建 " + S(l["build"]) + "，Luatools_v3.exe " + S(l["exe_size"]) + " 字节）");
            log("  脚本资源      " + S(l["resource_version"]) + "（resource\\soc_script\\" + S(l["resource_version"]) + "\\lib）");
            log("  底包 SoC      " + S(soc["name"]) + "（sha256 " + S(soc["sha256"]).Substring(0, 16) + "…，" + S(soc["where"]) + "）");
            var mine = ((ArrayList)d["files"]).Cast<object>().Select(D).Where(f => ((ArrayList)f["used_by"]).Cast<object>().Select(S).Contains(tool)).ToList();
            log("  本工具用到的 " + mine.Count + " 个文件：");
            foreach (var f in mine)
            {
                string rel = S(D(f["bundled"])[tool]);
                string p = Path.Combine(dir, rel.Replace('/', Path.DirectorySeparatorChar));
                string state;
                if (!File.Exists(p)) { state = "缺失（必须处理）"; attention++; }
                else if (Sha(p) != S(f["sha256"])) { state = "与依赖表不符（必须处理：文件被改动或损坏）"; attention++; }
                else state = "与依赖表一致";
                say(state.StartsWith("与依赖表一致") ? null : "red", string.Format("    {0,-20} {1}  {2}  [{3}]", S(f["name"]), S(f["role"]), S(f["sha256"]).Substring(0, 12) + "…", state));
            }
            if (luatools == null) { log("  （没有选择已安装的 Luatools 目录，未做与本机 Luatools 的比较；选择后可检查是否需要升级）"); return attention; }

            log("[与本机 Luatools 比较] " + luatools);
            if (!File.Exists(Path.Combine(luatools, "Luatools_v3.exe")) && !Directory.Exists(Path.Combine(luatools, "_temp"))) { say("red", "  ERROR 这不像是 Luatools 目录（没有 Luatools_v3.exe 或 _temp），请重新选择"); return attention + 1; }
            string ver = InstalledVersion(luatools);
            if (ver == null) say(null, "  提示  无法从日志确认已安装的 Luatools 版本（先打开过一次 Luatools 才有日志），不影响使用");
            else if (ver == S(l["version"])) say(null, "  OK    Luatools 版本 " + ver + "，与工具包验证过的版本相同");
            else { say("green", "  提示  已安装的 Luatools 是 " + ver + "，工具包验证的是 " + S(l["version"]) + "：不影响工具使用（工具用自带文件）；只是用 Luatools 新版本去刷机时，它的行为未经验证"); notices++; }

            var changed = new List<string>();
            foreach (var f in mine)
            {
                string lp = S(f["luatools_path"]).Replace("{resource}", S(l["resource_version"]));
                if (lp.Length == 0) continue;
                string p = Path.Combine(luatools, lp.Replace('/', Path.DirectorySeparatorChar));
                if (!File.Exists(p)) { say("green", "  提示  " + S(f["name"]) + "：本机 Luatools 里没有 " + lp + "（不影响工具使用）"); changed.Add(S(f["name"])); notices++; }
                else if (Sha(p) != S(f["sha256"])) { say("green", "  提示  " + S(f["name"]) + "：本机 Luatools 的版本已变化（" + lp + "），不影响工具使用"); changed.Add(S(f["name"])); notices++; }
                else say(null, "  OK    " + S(f["name"]) + " 与本机 Luatools 相同");
            }

            // newer script resources shipped by a Luatools upgrade: which of the pinned libs differ?
            string res = Path.Combine(luatools, "resource", "soc_script");
            if (Directory.Exists(res))
            {
                var versions = Directory.GetDirectories(res, "v*").Select(Path.GetFileName).OrderBy(x => x, StringComparer.Ordinal).ToList();
                log("  脚本资源版本（本机）：" + string.Join("、", versions));
                var libs = ((ArrayList)d["files"]).Cast<object>().Select(D).Where(f => S(f["kind"]) == "lib").ToList();
                foreach (string v in versions.Where(x => string.CompareOrdinal(x, S(l["resource_version"])) > 0))
                {
                    var diff = new List<string>();
                    foreach (var f in libs)
                    {
                        string p = Path.Combine(res, v, "lib", S(f["name"]));
                        if (!File.Exists(p) || Sha(p) != S(f["sha256"])) diff.Add(S(f["name"]));
                    }
                    if (diff.Count > 0) { say("green", "  提示  较新的脚本资源 " + v + " 中这些厂商库与工具包不同：" + string.Join("、", diff) + "（不影响现有设备和工具，可继续使用）"); notices++; changed.AddRange(diff.Select(x => x + "@" + v)); }
                    else log("  OK    较新的脚本资源 " + v + " 的厂商库与工具包相同");
                }
            }

            if (attention > 0) say("red", "结论：必须处理：工具包自带的文件缺失或被改动，工具不能放心使用。请重新拿一份完整的工具包（不要自己替换文件）。");
            else if (notices == 0) say("green", "结论：本机 Luatools 与工具包依赖一致，无需升级。");
            else
            {
                say("green", "结论：不影响使用，不用升级。本机 Luatools 比工具包新（" + string.Join("、", changed.Distinct()) + "），但工具只用自带的固定文件，现有设备、已生成的刷机目录和 OTA 包都不受影响。");
                say(null, "  只有当你决定让设备也改用新的厂商库时才需要升级：那会改变设备固件的组成，必须由工具维护人用新库重新生成、实板验证后发新的工具包；在那之前继续使用现有工具包。");
            }
            return attention;
        }
    }
}
